-- DalaTech (tenant #0): the approved look, the thank-you and greeting replies (founder,
-- 2026-09-26, D-133). Tara is not touched: every statement is keyed on slug 'dalatech'.
--
-- Rows only. What reaches the compiled prefix (the service rename, the name line) is live
-- only after a republish through scripts/publish/tenant.ts; everything else is read per
-- request and is live the moment this commits.
--
--  1. tenants.reply_style (0055): «💬 {service}» / «💰 {option}: {price}», at most one emoji
--     in the model's own words, none on a complaint or a refusal.
--  2. The service «Дали — Хүлээн авагч» is «Дали — AI хүлээн авагч», as in the approved look;
--     its knowledge document title follows. [prefix: republish]
--  3. A knowledge line naming the company and the assistant: a greeting reply had called the
--     product «Дала апп», and nothing in the prefix named DalaTech at all. [prefix: republish]
--  4. The follow-up line, replaced by the approved text, exactly.
--  5. A whole-message thank-you reply and a whole-message greeting reply. The greeting is the
--     approved introduction, served whole, so a plain greeting gets a short greeting only.
--  6. Every permanent case that expected the old follow-up; st1 / sg1 / sg2 made exact.
--     Case 20 is switched back on separately, after its repeat runs.
begin;

do $$
begin
  if not exists (select 1 from tenants where slug = 'dalatech') then
    raise exception 'no tenant with slug dalatech';
  end if;
end
$$;

update tenants set reply_style = '{"price_header": "💬 {service}", "price_line": "💰 {option}: {price}", "max_emoji": 1}'::jsonb
where slug = 'dalatech';

update services s set name = normalize('Дали — AI хүлээн авагч', NFC)
from tenants t where s.tenant_id = t.id and t.slug = 'dalatech' and s.name = 'Дали — Хүлээн авагч';

update knowledge_documents k set title = normalize(replace(k.title, 'Дали — Хүлээн авагч', 'Дали — AI хүлээн авагч'), NFC)
from tenants t where k.tenant_id = t.id and t.slug = 'dalatech' and k.title like 'Дали — Хүлээн авагч%';

insert into knowledge_documents (tenant_id, title, body, source)
select t.id, 'Нэр', normalize(E'- Манай компанийн нэр: DalaTech.\n- AI туслахын нэр: Дали.\n- Өөр нэр зохиож хэрэглэхгүй.', NFC),
       'founder 2026-09-26'
from tenants t where t.slug = 'dalatech'
  and not exists (select 1 from knowledge_documents k where k.tenant_id = t.id and k.title = 'Нэр');

update sales_next_steps n set body = normalize(E'🤖 Таны Facebook, Instagram, вэбсайтын зурваст 24/7 хариулна.\n🎁 Үнэгүй демо, 24 цагт бэлэн: https://app.dalatech.online\n👉 Бусад AI ажилтнууд: https://dalatech.online', NFC), reviewed_at = '2026-09-26T00:00:00Z'
from tenants t where n.tenant_id = t.id and t.slug = 'dalatech' and n.kind = 'follow_up';

insert into deterministic_replies (tenant_id, intent, body, enabled, match_mode, stems, placement, provenance)
select t.id, 'thanks', normalize('Зүгээр ээ 😊 Өөр асуух зүйл байвал бичээрэй.', NFC), true, 'whole_message',
       array['баярлалаа', 'их баярлалаа', 'за баярлалаа', 'баярлалаа танд', 'танд баярлалаа', 'маш их баярлалаа', 'bayarlalaa', 'bayrlalaa', 'bayarllaa', 'bayrllaa', 'ih bayarlalaa', 'za bayarlalaa', 'mash ih bayarlalaa', 'thanks', 'thank you', 'thanks a lot', 'thx', 'ok thanks']::text[], 'replace', 'tenant_confirmed'
from tenants t where t.slug = 'dalatech'
on conflict (tenant_id, intent) do update set body = excluded.body, stems = excluded.stems, enabled = true,
  match_mode = excluded.match_mode, placement = excluded.placement, provenance = excluded.provenance;

insert into deterministic_replies (tenant_id, intent, body, enabled, match_mode, stems, placement, provenance)
select t.id, 'greeting', d.body, true, 'whole_message', array['сайн байна уу', 'сайн уу', 'сайн бна уу', 'сайн бну', 'сн бну', 'сайн байцгаана уу', 'оройн мэнд', 'өглөөний мэнд', 'өдрийн мэнд', 'мэнд', 'мэнд хүргэе', 'sain baina uu', 'sain bnuu', 'sain bnu', 'sn bnu', 'sainuu', 'sain uu', 'hi', 'hii', 'hello', 'hey', 'hi dali', 'hello dali']::text[], 'replace', 'tenant_confirmed'
from tenants t join deterministic_replies d on d.tenant_id = t.id and d.intent = 'assistant_who'
where t.slug = 'dalatech'
on conflict (tenant_id, intent) do update set body = excluded.body, stems = excluded.stems, enabled = true,
  match_mode = excluded.match_mode, placement = excluded.placement, provenance = excluded.provenance;

-- The founder's own price case (id 9, not from a set file).
update reply_cases r set expected_body = replace(r.expected_body, E'Дали бол таны бизнесийн Facebook, Instagram, вэбсайтад ирсэн зурваст 24/7 хариулдаг AI ажилтан.\nҮнэгүй демо вэбсайт авахыг хүсвэл: https://app.dalatech.online — 24 цагийн дотор бэлэн болно.\nМанай бусад AI ажилтнуудтай https://dalatech.online дээр танилцаарай, эсвэл асуух зүйлээ энд бичээрэй.', E'🤖 Таны Facebook, Instagram, вэбсайтын зурваст 24/7 хариулна.\n🎁 Үнэгүй демо, 24 цагт бэлэн: https://app.dalatech.online\n👉 Бусад AI ажилтнууд: https://dalatech.online')
from tenants t where r.tenant_id = t.id and t.slug = 'dalatech' and r.expected_body like '%24/7 хариулдаг AI ажилтан%';

